        fill.dataset.dpFill = "";
        fill.setAttribute("aria-hidden", "true");
        fill.className = `absolute inset-0 rounded-lg bg-brand shadow-[0_4px_10px_-4px_color-mix(in_srgb,var(--brand)_70%,transparent)]${fresh ? "" : " asta-dp-pop"}`;
        b.prepend(fill);
